const pptxgen = require("pptxgenjs");

// ============================================================
// DESIGN SYSTEM
// ============================================================
// Palette: Ocean Gradient / Deep Climate — authoritative, data-forward
const C = {
  deepBlue: "065A82",
  teal: "1C7293",
  midnight: "21295C",
  ice: "E0F7FA",
  slate: "475569",
  white: "FFFFFF",
  coral: "F96167",
  sand: "F8FAFC",
  darkText: "1E293B",
  mutedText: "64748B",
  gridLine: "E2E8F0",
  accentGreen: "10B981",
  accentOrange: "F59E0B",
  accentRed: "EF4444",
};

const F = {
  header: "Trebuchet MS",
  body: "Calibri",
};

const S = {
  title: { fontSize: 36, fontFace: F.header, color: C.darkText, bold: true },
  titleWhite: { fontSize: 36, fontFace: F.header, color: C.white, bold: true },
  subtitle: { fontSize: 18, fontFace: F.body, color: C.mutedText },
  subtitleWhite: { fontSize: 18, fontFace: F.body, color: C.ice },
  body: { fontSize: 16, fontFace: F.body, color: C.darkText },
  bodyWhite: { fontSize: 16, fontFace: F.body, color: C.white },
  caption: { fontSize: 11, fontFace: F.body, color: C.mutedText },
  stat: { fontSize: 60, fontFace: F.header, color: C.deepBlue, bold: true },
  statLabel: { fontSize: 14, fontFace: F.body, color: C.mutedText },
  sectionHeader: { fontSize: 20, fontFace: F.header, color: C.deepBlue, bold: true },
};

function makeShadow() {
  return { type: "outer", color: "000000", blur: 6, offset: 2, angle: 135, opacity: 0.12 };
}

// ============================================================
// PRESENTATION SETUP
// ============================================================
let pres = new pptxgen();
pres.layout = "LAYOUT_16x9";
pres.title = "Global CO₂ Emissions: Trends, Regional Shifts, and Per Capita Inequalities";
pres.author = "Climate Data Brief";
pres.subject = "Global CO₂ Emissions Analysis";

// ============================================================
// SLIDE 1 — TITLE
// ============================================================
{
  let slide = pres.addSlide();
  slide.background = { color: C.midnight };

  // Decorative top bar
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 10, h: 0.12,
    fill: { color: C.teal }, line: { color: C.teal, width: 0 },
  });

  // Large background accent shape
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 3.8, w: 10, h: 1.825,
    fill: { color: C.deepBlue, transparency: 30 }, line: { color: C.deepBlue, width: 0 },
  });

  slide.addText("Global CO₂ Emissions", {
    x: 0.6, y: 1.6, w: 8.8, h: 0.7,
    fontSize: 44, fontFace: F.header, color: C.white, bold: true,
  });

  slide.addText("Trends, Regional Shifts, and Per Capita Inequalities", {
    x: 0.6, y: 2.3, w: 8.8, h: 0.5,
    fontSize: 22, fontFace: F.body, color: C.ice,
  });

  slide.addText("1750 — 2024", {
    x: 0.6, y: 2.85, w: 8.8, h: 0.4,
    fontSize: 18, fontFace: F.body, color: C.teal, bold: true,
  });

  slide.addText("Data: Global Carbon Budget 2025 • NASA / NOAA Mauna Loa Observatory", {
    x: 0.6, y: 4.3, w: 8.8, h: 0.35,
    fontSize: 12, fontFace: F.body, color: C.ice, italic: true,
  });

  slide.addText("Prepared for Policy Analysts & Climate Negotiators", {
    x: 0.6, y: 4.7, w: 8.8, h: 0.3,
    fontSize: 12, fontFace: F.body, color: C.mutedText,
  });
}

// ============================================================
// SLIDE 2 — ATMOSPHERIC CO₂ MILESTONE
// ============================================================
{
  let slide = pres.addSlide();
  slide.background = { color: C.sand };

  // Top accent bar
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 10, h: 0.08,
    fill: { color: C.coral }, line: { color: C.coral, width: 0 },
  });

  slide.addText("Atmospheric CO₂ Reaches 429 ppm", {
    x: 0.5, y: 0.35, w: 9, h: 0.6,
    ...S.title,
  });
  slide.addText("50% Above Pre-Industrial Levels", {
    x: 0.5, y: 0.9, w: 9, h: 0.35,
    ...S.subtitle,
  });

  // Big stat callout card
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 1.5, w: 4.2, h: 2.2,
    fill: { color: C.white },
    shadow: makeShadow(),
  });
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 1.5, w: 0.08, h: 2.2,
    fill: { color: C.coral },
  });

  slide.addText("429", {
    x: 0.7, y: 1.65, w: 3.8, h: 0.9,
    fontSize: 72, fontFace: F.header, color: C.coral, bold: true,
  });
  slide.addText("parts per million", {
    x: 0.7, y: 2.45, w: 3.8, h: 0.3,
    fontSize: 16, fontFace: F.body, color: C.mutedText,
  });
  slide.addText("NOAA Mauna Loa — February 2026", {
    x: 0.7, y: 2.8, w: 3.8, h: 0.25,
    fontSize: 12, fontFace: F.body, color: C.mutedText, italic: true,
  });

  // Timeline / context cards
  const cardW = 2.6, cardH = 1.1, startX = 5.1, startY = 1.5, gap = 0.25;
  const timeline = [
    { year: "~280 ppm", label: "Pre-industrial baseline", color: C.teal },
    { year: "1.5×", label: "Faster than last ice-age rise", color: C.deepBlue },
    { year: "~200 years", label: "Time span of current increase", color: C.midnight },
  ];
  timeline.forEach((item, i) => {
    let cx = startX + (i % 2) * (cardW + gap);
    let cy = startY + Math.floor(i / 2) * (cardH + gap);
    slide.addShape(pres.shapes.RECTANGLE, {
      x: cx, y: cy, w: cardW, h: cardH,
      fill: { color: C.white }, shadow: makeShadow(),
    });
    slide.addShape(pres.shapes.RECTANGLE, {
      x: cx, y: cy, w: cardW, h: 0.06,
      fill: { color: item.color },
    });
    slide.addText(item.year, {
      x: cx + 0.15, y: cy + 0.2, w: cardW - 0.3, h: 0.35,
      fontSize: 20, fontFace: F.header, color: item.color, bold: true,
    });
    slide.addText(item.label, {
      x: cx + 0.15, y: cy + 0.55, w: cardW - 0.3, h: 0.35,
      fontSize: 13, fontFace: F.body, color: C.mutedText,
    });
  });

  // Bottom annotation
  slide.addText(
    "Ground-based and satellite measurements confirm the sharp acceleration, linked primarily to the burning of coal, oil, and natural gas.",
    { x: 0.5, y: 4.0, w: 9, h: 0.6, ...S.body, italic: true }
  );
}

// ============================================================
// SLIDE 3 — GLOBAL EMISSIONS TRAJECTORY
// ============================================================
{
  let slide = pres.addSlide();
  slide.background = { color: C.sand };

  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 10, h: 0.08,
    fill: { color: C.teal }, line: { color: C.teal, width: 0 },
  });

  slide.addText("Global Fossil Fuel CO₂ Emissions Grew Six-Fold", {
    x: 0.5, y: 0.35, w: 9, h: 0.6,
    ...S.title,
  });
  slide.addText("6 Billion Tonnes in 1950 → 35+ Billion Tonnes Today", {
    x: 0.5, y: 0.9, w: 9, h: 0.35,
    ...S.subtitle,
  });

  // Key milestone stats
  const milestones = [
    { year: "1950", val: "6 Bt", note: "Post-war industrial take-off" },
    { year: "1990", val: "20 Bt", note: "Nearly quadrupled in 40 years" },
    { year: "2024", val: "35+ Bt", note: "Growth slowed, but not yet peaked" },
  ];
  milestones.forEach((m, i) => {
    let x = 0.5 + i * 3.1;
    slide.addShape(pres.shapes.RECTANGLE, {
      x, y: 1.45, w: 2.8, h: 1.5,
      fill: { color: C.white }, shadow: makeShadow(),
    });
    slide.addShape(pres.shapes.RECTANGLE, {
      x, y: 1.45, w: 2.8, h: 0.06,
      fill: { color: i === 2 ? C.coral : C.teal },
    });
    slide.addText(m.val, {
      x: x + 0.15, y: 1.6, w: 2.5, h: 0.5,
      fontSize: 32, fontFace: F.header, color: i === 2 ? C.coral : C.deepBlue, bold: true,
    });
    slide.addText(m.year, {
      x: x + 0.15, y: 2.1, w: 2.5, h: 0.3,
      fontSize: 16, fontFace: F.body, color: C.mutedText, bold: true,
    });
    slide.addText(m.note, {
      x: x + 0.15, y: 2.4, w: 2.5, h: 0.35,
      fontSize: 12, fontFace: F.body, color: C.mutedText,
    });
  });

  // Reference figure placeholder area
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 3.2, w: 9, h: 1.9,
    fill: { color: C.white }, shadow: makeShadow(),
  });
  slide.addText("Reference: figure_2.jpg — Annual CO₂ emissions trajectory (1750–2024)", {
    x: 0.7, y: 3.3, w: 8.6, h: 0.3,
    fontSize: 12, fontFace: F.body, color: C.mutedText, italic: true,
  });
  // Simple line chart illustration using PptxGenJS chart
  slide.addChart(pres.charts.LINE, [{
    name: "Global CO₂ (Bt)",
    labels: ["1750", "1850", "1900", "1950", "1970", "1990", "2010", "2024"],
    values: [0.01, 0.2, 2.0, 6.0, 14.0, 20.5, 33.0, 37.0],
  }], {
    x: 0.7, y: 3.6, w: 8.6, h: 1.35,
    lineSize: 3, lineSmooth: true,
    chartColors: [C.teal],
    chartArea: { fill: { color: C.white } },
    catAxisLabelColor: C.mutedText,
    valAxisLabelColor: C.mutedText,
    valGridLine: { color: C.gridLine, size: 0.5 },
    catGridLine: { style: "none" },
    showLegend: false,
    showValue: false,
  });
}

// ============================================================
// SLIDE 4 — CHINA SURPASSES US
// ============================================================
{
  let slide = pres.addSlide();
  slide.background = { color: C.sand };

  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 10, h: 0.08,
    fill: { color: C.deepBlue }, line: { color: C.deepBlue, width: 0 },
  });

  slide.addText("China Now Emits Over 12 Billion Tonnes", {
    x: 0.5, y: 0.35, w: 9, h: 0.6,
    ...S.title,
  });
  slide.addText("More Than Double the United States", {
    x: 0.5, y: 0.9, w: 9, h: 0.35,
    ...S.subtitle,
  });

  // Data table
  const tableX = 0.5, tableY = 1.45, tableW = 5.0, rowH = 0.42;
  const headers = ["Country / Region", "Annual CO₂ (Bt)", "Global Share", "Trend"];
  const rows = [
    ["China", "~12.5", "~27%", "Slight increase"],
    ["United States", "~5.0", "~14%", "Declining"],
    ["India", "~3.0", "~8%", "Rising"],
    ["EU-27", "~2.7", "~7%", "Declining"],
    ["Germany", "~0.6", "~1.7%", "Declining"],
    ["United Kingdom", "~0.3", "~0.9%", "Declining"],
    ["Brazil", "~0.5", "~1.4%", "Roughly stable"],
    ["France", "~0.3", "~0.8%", "Declining"],
  ];

  let tableData = [
    headers.map(h => ({ text: h, options: { fill: { color: C.deepBlue }, color: C.white, bold: true, fontSize: 13, fontFace: F.body } })),
  ];
  rows.forEach((r, idx) => {
    let bg = idx % 2 === 0 ? C.white : "F1F5F9";
    tableData.push(r.map(c => ({ text: c, options: { fill: { color: bg }, color: C.darkText, fontSize: 12, fontFace: F.body } })));
  });

  slide.addTable(tableData, {
    x: tableX, y: tableY, w: tableW,
    colW: [1.8, 1.1, 1.0, 1.1],
    border: { pt: 0.5, color: C.gridLine },
    rowH,
    valign: "middle",
  });

  // Right-side image reference
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 5.8, y: 1.45, w: 3.7, h: 3.5,
    fill: { color: C.white }, shadow: makeShadow(),
  });
  slide.addImage({
    path: "/app/benchmark/assets/figure_3.jpg",
    x: 5.9, y: 1.55, w: 3.5, h: 3.0,
    sizing: { type: "contain", w: 3.5, h: 3.0 },
  });
  slide.addText("figure_3.jpg — Annual CO₂ emissions by country", {
    x: 5.9, y: 4.6, w: 3.5, h: 0.25,
    fontSize: 10, fontFace: F.body, color: C.mutedText, italic: true, align: "center",
  });

  // Annotation
  slide.addText("The US peaked near 6 Bt around 2005 and has since declined to roughly 5 Bt. India's rise is rapid.", {
    x: 0.5, y: 4.55, w: 5.0, h: 0.5,
    fontSize: 12, fontFace: F.body, color: C.mutedText, italic: true,
  });
}

// ============================================================
// SLIDE 5 — REGIONAL SHARE SHIFT
// ============================================================
{
  let slide = pres.addSlide();
  slide.background = { color: C.sand };

  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 10, h: 0.08,
    fill: { color: C.midnight }, line: { color: C.midnight, width: 0 },
  });

  slide.addText("Asia Now Accounts for ~50% of Global Emissions", {
    x: 0.5, y: 0.35, w: 9, h: 0.6,
    ...S.title,
  });
  slide.addText("US + Europe Combined Have Fallen Below One-Third", {
    x: 0.5, y: 0.9, w: 9, h: 0.35,
    ...S.subtitle,
  });

  // 1900 vs 2024 comparison
  const compareY = 1.5;
  const boxW = 4.2, boxH = 2.6;

  // 1900 box
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: compareY, w: boxW, h: boxH,
    fill: { color: C.white }, shadow: makeShadow(),
  });
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: compareY, w: boxW, h: 0.06,
    fill: { color: C.teal },
  });
  slide.addText("1900", {
    x: 0.7, y: compareY + 0.2, w: 3.8, h: 0.4,
    fontSize: 28, fontFace: F.header, color: C.teal, bold: true,
  });
  slide.addText("Europe + United States", {
    x: 0.7, y: compareY + 0.65, w: 3.8, h: 0.3,
    fontSize: 16, fontFace: F.body, color: C.darkText, bold: true,
  });
  slide.addText("> 90%", {
    x: 0.7, y: compareY + 1.0, w: 3.8, h: 0.6,
    fontSize: 48, fontFace: F.header, color: C.deepBlue, bold: true,
  });
  slide.addText("of global CO₂ emissions", {
    x: 0.7, y: compareY + 1.55, w: 3.8, h: 0.3,
    fontSize: 13, fontFace: F.body, color: C.mutedText,
  });

  // Arrow
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 4.9, y: compareY + 1.1, w: 1.2, h: 0.12,
    fill: { color: C.coral },
  });
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 5.9, y: compareY + 0.95, w: 0.3, h: 0.42,
    fill: { color: C.coral },
  });
  // small arrow tip triangle-ish via rotated rect
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 6.05, y: compareY + 0.9, w: 0.25, h: 0.52,
    fill: { color: C.coral }, rotate: 45,
  });

  // 2024 box
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 5.3, y: compareY, w: boxW, h: boxH,
    fill: { color: C.white }, shadow: makeShadow(),
  });
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 5.3, y: compareY, w: boxW, h: 0.06,
    fill: { color: C.coral },
  });
  slide.addText("2024", {
    x: 5.5, y: compareY + 0.2, w: 3.8, h: 0.4,
    fontSize: 28, fontFace: F.header, color: C.coral, bold: true,
  });
  slide.addText("Asia", {
    x: 5.5, y: compareY + 0.65, w: 3.8, h: 0.3,
    fontSize: 16, fontFace: F.body, color: C.darkText, bold: true,
  });
  slide.addText("~50%", {
    x: 5.5, y: compareY + 1.0, w: 3.8, h: 0.6,
    fontSize: 48, fontFace: F.header, color: C.coral, bold: true,
  });
  slide.addText("of global CO₂ emissions", {
    x: 5.5, y: compareY + 1.55, w: 3.8, h: 0.3,
    fontSize: 13, fontFace: F.body, color: C.mutedText,
  });

  // Bottom stat row
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 4.35, w: 9, h: 0.9,
    fill: { color: C.white }, shadow: makeShadow(),
  });
  slide.addText("Africa and South America each contribute only 3–4%, comparable to international aviation and shipping combined.", {
    x: 0.7, y: 4.45, w: 8.6, h: 0.35,
    fontSize: 14, fontFace: F.body, color: C.darkText, italic: true,
  });
  slide.addText("US + Europe today: < 33%  •  Asia: ~50%  •  Rest of world: ~17–20%", {
    x: 0.7, y: 4.8, w: 8.6, h: 0.3,
    fontSize: 12, fontFace: F.body, color: C.mutedText,
  });
}

// ============================================================
// SLIDE 6 — PER CAPITA 150× GAP
// ============================================================
{
  let slide = pres.addSlide();
  slide.background = { color: C.sand };

  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 10, h: 0.08,
    fill: { color: C.coral }, line: { color: C.coral, width: 0 },
  });

  slide.addText("Per Capita Gap: 15 t in the US vs. 0.1 t in Chad", {
    x: 0.5, y: 0.35, w: 9, h: 0.6,
    ...S.title,
  });
  slide.addText("A 150× Disparity", {
    x: 0.5, y: 0.9, w: 9, h: 0.35,
    ...S.subtitle,
  });

  // Horizontal bar chart using PptxGenJS
  const barData = [
    { name: "Per Capita CO₂", labels: ["United States", "Canada", "China", "EU-27", "World avg", "UK", "India", "Kenya / Chad"], values: [15, 13, 9, 7, 5, 4, 2, 0.1] },
  ];
  slide.addChart(pres.charts.BAR, barData, {
    x: 0.5, y: 1.45, w: 6.0, h: 3.5,
    barDir: "bar",
    chartColors: [C.coral],
    chartArea: { fill: { color: C.white }, roundedCorners: true },
    catAxisLabelColor: C.darkText,
    valAxisLabelColor: C.mutedText,
    valGridLine: { color: C.gridLine, size: 0.5 },
    catGridLine: { style: "none" },
    showLegend: false,
    showValue: true,
    dataLabelPosition: "outEnd",
    dataLabelColor: C.darkText,
    dataLabelFontSize: 11,
    catAxisLabelFontSize: 11,
    valAxisLabelFontSize: 10,
    title: "Tonnes CO₂ per person per year",
    titleFontSize: 12,
    titleColor: C.mutedText,
    titleBold: false,
  });

  // Right-side callout box
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 6.8, y: 1.45, w: 2.7, h: 3.5,
    fill: { color: C.white }, shadow: makeShadow(),
  });
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 6.8, y: 1.45, w: 2.7, h: 0.06,
    fill: { color: C.midnight },
  });

  slide.addText("150×", {
    x: 7.0, y: 1.7, w: 2.3, h: 0.7,
    fontSize: 48, fontFace: F.header, color: C.coral, bold: true,
  });
  slide.addText("gap between highest and lowest per capita emitters", {
    x: 7.0, y: 2.35, w: 2.3, h: 0.5,
    fontSize: 13, fontFace: F.body, color: C.darkText,
  });
  slide.addText("The average American emits in under two days what the average person in Chad or Niger emits in an entire year.", {
    x: 7.0, y: 2.95, w: 2.3, h: 1.0,
    fontSize: 12, fontFace: F.body, color: C.mutedText, italic: true,
  });

  // Reference
  slide.addText("Reference: figure_1.jpg — Per capita CO₂ emissions over time", {
    x: 0.5, y: 5.05, w: 6.0, h: 0.25,
    fontSize: 10, fontFace: F.body, color: C.mutedText, italic: true,
  });
}

// ============================================================
// SLIDE 7 — 2024 ANNUAL CHANGE MAP
// ============================================================
{
  let slide = pres.addSlide();
  slide.background = { color: C.sand };

  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 10, h: 0.08,
    fill: { color: C.accentGreen }, line: { color: C.accentGreen, width: 0 },
  });

  slide.addText("2024 Snapshot: US and Europe Cut Emissions", {
    x: 0.5, y: 0.35, w: 9, h: 0.6,
    ...S.title,
  });
  slide.addText("Russia and Southeast Asia Increase", {
    x: 0.5, y: 0.9, w: 9, h: 0.35,
    ...S.subtitle,
  });

  // Image
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 1.45, w: 5.5, h: 3.6,
    fill: { color: C.white }, shadow: makeShadow(),
  });
  slide.addImage({
    path: "/app/benchmark/assets/figure_4.jpg",
    x: 0.6, y: 1.55, w: 5.3, h: 3.4,
    sizing: { type: "contain", w: 5.3, h: 3.4 },
  });
  slide.addText("figure_4.jpg — Annual % change in CO₂ emissions, 2024", {
    x: 0.6, y: 5.0, w: 5.3, h: 0.2,
    fontSize: 10, fontFace: F.body, color: C.mutedText, italic: true, align: "center",
  });

  // Legend / key
  const legendX = 6.3, legendY = 1.45, legendW = 3.2;
  slide.addShape(pres.shapes.RECTANGLE, {
    x: legendX, y: legendY, w: legendW, h: 3.6,
    fill: { color: C.white }, shadow: makeShadow(),
  });
  slide.addShape(pres.shapes.RECTANGLE, {
    x: legendX, y: legendY, w: legendW, h: 0.06,
    fill: { color: C.deepBlue },
  });
  slide.addText("Regional Patterns", {
    x: legendX + 0.15, y: legendY + 0.15, w: legendW - 0.3, h: 0.35,
    fontSize: 16, fontFace: F.header, color: C.deepBlue, bold: true,
  });

  const patterns = [
    { color: C.accentGreen, label: "United States & much of Europe", val: "−1% to −5%" },
    { color: C.accentOrange, label: "Russia, parts of SE Asia, Africa", val: "+2% to +10%" },
    { color: C.accentRed, label: "Some South American nations", val: "> +10%" },
